const smoothstep = (x) => x * x * (3 - 2 * x);

/**
 * Build a flythrough rig from keyframes.
 * @param {Array<{timeSec: number, position: Vector3, target: Vector3}>} keys
 *        sorted ascending by timeSec.
 * @returns {{keys: Array<{timeSec: number, position: Vector3, target: Vector3}>}}
 */
export function makeFlythrough(keys) {
  if (!Array.isArray(keys) || keys.length < 2) {
    throw new Error('makeFlythrough requires at least two keyframes');
  }
  for (let i = 1; i < keys.length; i++) {
    if (keys[i].timeSec <= keys[i - 1].timeSec) {
      throw new Error('keyframes must be sorted by strictly increasing timeSec');
    }
  }
  // Copy so the rig owns its keyframe data.
  return {
    keys: keys.map((k) => ({
      timeSec: k.timeSec,
      position: k.position.clone(),
      target: k.target.clone(),
    })),
  };
}

// Scratch objects shared per call chain; poseAt must stay re-entrant-safe,
// so allocate fresh outputs but reuse nothing across calls that the caller
// could observe. A single module-level temp Object3D is fine since lookAt
// fully determines orientation each call.
const _lookHelper = new Object3D();
const _forward = new Vector3(0, 0, -1);

/**
 * Sample the rig at time t (seconds).
 *
 * - Clamps t to [firstKey.timeSec, lastKey.timeSec].
 * - Finds the bracketing keys, applies smoothstep easing to the local
 *   parameter, and lerps position and target separately.
 * - Derives orientation from a temp Object3D lookAt.
 *
 * @returns {{timeSec: number, position: Vector3, target: Vector3, quaternion: Quaternion}}
 */
export function poseAt(rig, t) {
  const { keys } = rig;
  const first = keys[0];
  const last = keys[keys.length - 1];

  const tc = Math.min(Math.max(t, first.timeSec), last.timeSec);

  // Find bracketing segment: last i such that keys[i].timeSec <= tc.
  let i = 0;
  while (i < keys.length - 2 && keys[i + 1].timeSec <= tc) i++;
  const k0 = keys[i];
  const k1 = keys[i + 1];

  const span = k1.timeSec - k0.timeSec;
  const local = span === 0 ? 0 : (tc - k0.timeSec) / span;
  const s = smoothstep(local);

  const position = k0.position.clone().lerp(k1.position, s);
  const target = k0.target.clone().lerp(k1.target, s);

  _lookHelper.position.copy(position);
  _lookHelper.up.set(0, 1, 0);
  _lookHelper.lookAt(target);
  const quaternion = _lookHelper.quaternion.clone();

  return { timeSec: tc, position, target, quaternion };
}

/** Unit forward vector (-Z transformed by the pose quaternion). */
export function forwardOf(pose) {
  return _forward.clone().applyQuaternion(pose.quaternion).normalize();
}
"})
