result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/flythrough.test.js", "content": "import { describe, it, expect } from 'vitest';
import { Vector3, Quaternion } from 'three';
import { makeFlythrough, poseAt, forwardOf } from '../src/flythrough.js';

const KEYS = [
  { timeSec: 0, position: new Vector3(0, 0, 10), target: new Vector3(0, 0, 0) },
  { timeSec: 2, position: new Vector3(6, 2, 6), target: new Vector3(1, 1, 0) },
  { timeSec: 5, position: new Vector3(8, 4, -4), target: new Vector3(2, 2, 0) },
  { timeSec: 9, position: new Vector3(-2, 6, -12), target: new Vector3(0, 3, 0) },
];

const rig = makeFlythrough(KEYS);

const smoothstep = (x) => x * x * (3 - 2 * x);

/** Independent reference pose (no shared code with the implementation). */
function refPose(t) {
  const tc = Math.min(Math.max(t, KEYS[0].timeSec), KEYS[KEYS.length - 1].timeSec);
  let i = 0;
  while (i < KEYS.length - 2 && KEYS[i + 1].timeSec <= tc) i++;
  const a = KEYS[i];
  const b = KEYS[i + 1];
  const s = smoothstep((tc - a.timeSec) / (b.timeSec - a.timeSec));
  const pos = new Vector3().lerpVectors(a.position, b.position, s);
  const tgt = new Vector3().lerpVectors(a.target, b.target, s);
  return {
    position: pos,
    target: tgt,
    quaternion: new Quaternion().setFromRotationMatrix(
      // Equivalent to Object3D.lookAt: orient -Z toward (target - position).
      new (require('three').Matrix4 ?? Object).constructor === Function
        ? lookAtMatrix(pos, tgt)
        : lookAtMatrix(pos, tgt)
    ),
  };
}

// Minimal standalone look-at matrix (right-handed, Y-up), built from scratch
// so the quaternion expectation is truly independent of three's lookAt path.
function lookAtMatrix(eye, targetPos) {
  const z = new Vector3().subVectors(eye, targetPos).normalize(); // camera looks down -Z
  const up = new Vector3(0, 1, 0);
  const x = new Vector3().crossVectors(up, z).normalize();
  const y = new Vector3().crossVectors(z, x);
  return [
    x.x, y.x, z.x, 0,
    x.y, y.y, z.y, 0,
    x.z, y.z, z.z, 0,
    0, 0, 0, 1,
  ];
}

function matrixToQuaternion(m) {
  // Shepperd's method on a column-major 4x4 array.
  const [m00, m10, m20,, m01, m11, m21,, m02, m12, m22] = m;
  const tr = m00 + m11 + m22;
  let q;
  if (tr > 0) {
    const S = Math.sqrt(tr + 1) * 2;
    q = [(m21 - m12) / S, (m02 - m20) / S, (m10 - m01) / S, 0.25 * S];
  } else if (m00 > m11 && m00 > m22) {
    const S = Math.sqrt(1 + m00 - m11 - m22) * 2;
    q = [0.25 * S, (m01 + m10) / S, (m02 + m20) / S, (m21 - m12) / S];
  } else if (m11 > m22) {
    const S = Math.sqrt(1 + m11 - m00 - m22) * 2;
    q = [(m01 + m10) / S, 0.25 * S, (m12 + m21) / S, (m02 - m20) / S];
  } else {
    const S = Math.sqrt(1 + m22 - m00 - m11) * 2;
    q = [(m02 + m20) / S, (m12 + m21) / S, 0.25 * S, (m10 - m01) / S];
  }
  return new Quaternion(q[0], q[1], q[2], q[3]);
}

describe('poseAt keyframe reproduction', () => {
  for (const key of KEYS) {
    it(`at t=${key.timeSec} reproduces the key's position exactly`, () => {
      const pose = poseAt(rig, key.timeSec);
      expect(pose.position.distanceTo(key.position)).toBeLessThanOrEqual(1e-9);
    });

    it(`at t=${key.timeSec} looks at the key's target`, () => {
      const pose = poseAt(rig, key.timeSec);
      const fwd = forwardOf(pose);
      const expected = new Vector3()
        .subVectors(key.target, key.position)
        .normalize();
      expect(fwd.angleTo(expected)).toBeLessThan(1e-6);
      for (let c = 0; c < 3; c++) {
        expect(Math.abs(fwd.getComponent(c) - expected.getComponent(c))).toBeLessThan(1e-6);
      }
    });
  }
});

describe('smoothstep blending', () => {
  it('at the midpoint of keys 0 and 1 the position matches an independently computed smoothstep blend', () => {
    const tMid = (KEYS[0].timeSec + KEYS[1].timeSec) / 2; // = 1
    const s = smoothstep(0.5); // 0.5 at midpoint, computed independently above
    const expected = new Vector3().lerpVectors(KEYS[0].position, KEYS[1].position, s);

    const pose = poseAt(rig, tMid);
    for (let c = 0; c < 3; c++) {
      expect(pose.position.getComponent(c)).toBeCloseTo(expected.getComponent(c), 9);
    }

    // Sanity: also verify against a non-midpoint sample where smoothstep
    // genuinely differs from linear interpolation.
    const t25 = KEYS[0].timeSec + 0.5 * (KEYS[1].timeSec - KEYS[0].timeSec);
    const s25 = smoothstep(0.25);
    const expected25 = new Vector3().lerpVectors(KEYS[0].position, KEYS[1].position, s25);
    const pose25 = poseAt(rig, t25);
    for (let c = 0; c < 3; c++) {
      expect(pose25.position.getComponent(c)).toBeCloseTo(expected25.getComponent(c), 9);
    }
  });

  it('easing pulls local parameter 0.25 closer to the earlier key than linear would', () => {
    const t = KEYS[0].timeSec + 0.25 * (KEYS[1].timeSec - KEYS[0].timeSec);
    const pose = poseAt(rig, t);
    const distToEarly = pose.position.distanceTo(KEYS[0].position);
    const linear = new Vector3().lerpVectors(
      KEYS[0].position,
      KEYS[1].position,
      0.25
    );
    const linearDist = linear.distanceTo(KEYS[0].position);
    expect(distToEarly).toBeLessThan(linearDist);
    expect(distToEarly).toBeCloseTo(linearDist * (smoothstep(0.25) / 0.25), 9);
  });
});

describe('clamping', () => {
  it('t = -1 clamps to key 0', () => {
    const pose = poseAt(rig, -1);
    expect(pose.position.equals(KEYS[0].position)).toBe(true);
    expect(pose.timeSec).toBe(KEYS[0].timeSec);
    const fwd = forwardOf(pose);
    const expected = new Vector3()
      .subVectors(KEYS[0].target, KEYS[0].position)
      .normalize();
    for (let c = 0; c < 3; c++) {
      expect(fwd.getComponent(c)).toBeCloseTo(expected.getComponent(c), 9);
    }
  });

  it('t = 100 clamps to the last key', () => {
    const lastKey = KEYS[KEYS.length - 1];
    const pose = poseAt(rig, 100);
    expect(pose.position.equals(lastKey.position)).toBe(true);
    expect(pose.timeSec).toBe(lastKey.timeSec);
    const fwd = forwardOf(pose);
    const expected = new Vector3()
      .subVectors(lastKey.target, lastKey.position)
      .normalize();
    for (let c = 0; c < 3; c++) {
      expect(fwd.getComponent(c)).toBeCloseTo(expected.getComponent(c), 9);
    }
  });
});
"})
